/* Guided discovery: progressive cards, a connected map and consistent navigation. */
'use strict';
const GUIDE_STATIONS=[
 {route:'process',title:'Discover the work',verb:'Choose task cards',output:'A process map',icon:'⌘',story:'Start with the problem. Choose the tasks that really happen, put them in order and reveal the waiting.',tip:'Name your problem → select task cards → arrange and edit.',links:[['process','Process builder'],['journey','Name your discovery goal']]},
 {route:'systems',title:'Connect the information',verb:'Choose system cards',output:'Systems + source ownership',icon:'▦',story:'Follow each handoff to the tools and records behind it. Identify who owns the information and how it stays current.',tip:'Choose a system type → review its details → name the source owner.',links:[['systems','Systems & source register'],['resources','Inventory templates']]},
 {route:'assessment',title:'Check the foundations',verb:'Choose observed practice',output:'Readiness + unresolved gaps',icon:'◎',story:'Assess the actual practice. Keep process, data, people and technology distinct; mark what you do not know.',tip:'Read the observation → choose a practice card → review the gaps.',links:[['assessment','Readiness assessment'],['report','Readiness report'],['opportunities','Opportunity ranking'],['roi','ROI calculator'],['methodology','Scoring explained']]},
 {route:'stress-test',title:'Test the messy moments',verb:'Choose an intervention',output:'A reviewed test + next action',icon:'◇',story:'Try a late vendor, a disputed status and missing updates. See what needs attention before a real pilot.',tip:'Choose a scenario → try a response → save the lesson.',links:[['stress-test','Portfolio challenges'],['canvas','Governance simulator'],['prompts','Prompt library']]},
 {route:'recommendations',title:'Improve, measure, repeat',verb:'Choose the next action',output:'An improvement plan',icon:'↗',story:'Choose a free improvement, record its outcome and return to reassess. Explore a paid blueprint only when it fits the work.',tip:'Select the next step → track an outcome → revisit your baseline.',links:[['recommendations','Recommended next steps'],['implementation','Implementation checklist'],['outcomes','Outcome tracker'],['pricing','Available blueprints & previews'],['brief','Executive brief']]}
];
let guideSelected=0;
function guideDetail(i){const s=GUIDE_STATIONS[i];return `<div><span class="eyebrow">STOP ${i+1} / HOW IT WORKS</span><h2>${s.title}</h2><p>${s.story}</p><p class="guide-instruction">${s.tip}</p><div class="guide-output"><small>YOU LEAVE WITH</small><strong>${s.output}</strong></div></div><div class="guide-detail-actions">${link(s.route,'Open this stage','button lime')}<div class="guide-tools">${s.links.slice(1).map(([r,t])=>link(r,t,'guide-text-link')).join('')}</div></div>`;}
function guideLanding(){const status=journeyStatus(),next=journeyNext();return `<section class="guide-landing"><div class="guide-heading"><div><span class="eyebrow">THE EFFICIENCY LABS EXPLORER</span><h1>A clearer picture.<br><em>One discovery at a time.</em></h1><p>Your route from “why is this so difficult?” to a practical improvement. Pick a stop to see what to do and what you will take away.</p></div><div class="guide-pass"><span>YOUR EXPLORER PASS</span><strong>${status.slice(0,4).filter(Boolean).length} / 4</strong><small>discovery milestones recorded</small>${link(GUIDE_STATIONS[next].route,status.some(Boolean)?'Continue my journey':'Start with my process','button olive')}<small>Progress reflects saved work, not certified readiness.</small></div></div><div class="explorer-map"><div class="map-caption"><span>START WITH THE WORK</span><span>FOLLOW THE NUMBERED STOPS · EXPLORE FREELY</span></div><div class="explorer-stations" role="group" aria-label="Explore the five journey stages">${GUIDE_STATIONS.map((s,i)=>`<button class="explorer-stop ${i===guideSelected?'is-selected':''}" data-guide-stop="${i}" aria-pressed="${i===guideSelected}" aria-controls="guide-detail"><span class="stop-top"><b>0${i+1}</b><span>${status[i]?'✓ Recorded':i===next?'Suggested next':'Explore'}</span></span><span class="stop-scene" aria-hidden="true"><span>${s.icon}</span><i></i><i></i></span><strong>${s.title}</strong><small>${s.verb}</small><span class="stop-arrow" aria-hidden="true">→</span></button>`).join('')}</div><div class="guide-loop"><span aria-hidden="true">↶</span> Return with new observations. Improve the work, then reassess.</div><div id="guide-detail" class="guide-detail" role="region" aria-label="Selected stage" aria-live="polite">${guideDetail(guideSelected)}</div></div><div class="guide-sidepaths"><div><span class="eyebrow">YOUR BASE</span>${link('workspace','My workspace','guide-text-link')}${link('partners','Client workspaces','guide-text-link')}</div><div><span class="eyebrow">SPECIALIST PATH</span>${link('coe','PMO & Change COE','guide-text-link')}${link('roadmap','Transformation roadmap','guide-text-link')}</div><div><span class="eyebrow">REFERENCE DESK</span>${link('frameworks','Frameworks','guide-text-link')}${link('resources','Resources & templates','guide-text-link')}${link('case-studies','Illustrative cases','guide-text-link')}${link('faq','Help & privacy','guide-text-link')}</div></div></section>`;}
function guideStageFor(r){if(['process','journey'].includes(r))return 0;if(r==='systems')return 1;if(['assessment','report','report-preview','opportunities','roi','roi-calculator','methodology'].includes(r))return 2;if(['stress-test','canvas','prompts'].includes(r))return 3;if(['recommendations','implementation','implementation-guide','outcomes','brief','executive-brief','pricing','specialist-blueprints','roadmap','transformation-roadmap','coe'].includes(r)||/^(tier|kit)-/.test(r))return 4;return -1;}
function guideRail(r){const active=guideStageFor(r);return `<section class="guide-wayfinding" aria-label="Your place in the journey"><div class="guide-where">${link('home','← Explorer map','guide-text-link')}<span>${active<0?'YOUR SUPPORT DESK':`STAGE ${active+1} / ${GUIDE_STATIONS[active].title.toUpperCase()}`}</span>${link('workspace','My workspace','guide-text-link')}</div><nav class="guide-rail" aria-label="Journey stages">${GUIDE_STATIONS.map((s,i)=>`<a href="#/${s.route}" ${active===i?'aria-current="step" class="active"':''}><b>${i+1}</b><span>${s.title}</span></a>`).join('')}</nav>${active>=0?`<div class="guide-stage-brief"><span><b>DO THIS</b> ${GUIDE_STATIONS[active].tip}</span><span><b>TAKE AWAY</b> ${GUIDE_STATIONS[active].output}</span></div>`:''}</section>`;}
function guideContinue(r){const i=guideStageFor(r);if(i<0)return `<div class="guide-return">${link('home','Return to the explorer map','button secondary')}${link(GUIDE_STATIONS[journeyNext()].route,'Continue my discovery','button olive')}</div>`;return `<div class="guide-return"><div><span class="eyebrow">${i===4?'CONTINUE THE IMPROVEMENT CYCLE':'WHEN YOU ARE READY'}</span><h3>${i===4?'Measure what changed. Return with evidence.':GUIDE_STATIONS[i+1].title}</h3><p>${i===4?'Keep your outcomes and reassessments comparable. Buying a blueprint is optional.':GUIDE_STATIONS[i+1].story}</p></div><div class="inline-actions">${link(i?GUIDE_STATIONS[i-1].route:'home',i?'← Previous stage':'← Explorer map','button secondary')}${link(i===4?'outcomes':GUIDE_STATIONS[i+1].route,i===4?'Track an outcome':'Next stage →','button olive')}${i===4?link('assessment','Reassess readiness','button secondary'):''}</div></div>`;}
const SYSTEM_STARTERS=[['Spreadsheet / tracker','Track workflow records and status','▦'],['CRM / customer platform','Maintain customer and service records','◎'],['Project / portfolio tool','Coordinate project milestones and updates','◇'],['ERP / finance system','Maintain finance and purchasing records','▤'],['Email / messaging','Exchange requests and decisions','✉'],['Document repository','Store controlled files and reference material','▱']];
const OUTCOME_STARTERS=[['Reporting effort','hours / reporting cycle','lower'],['Decision delay','days / exception','lower'],['On-time updates','percent / reporting cycle','higher'],['Rework rate','percent / completed cases','lower']];
function quickCards(title,help,items,kind){return `<section class="guided-choices"><div class="section-head"><div><span class="eyebrow">CHOOSE A STARTING POINT</span><h2>${title}</h2></div><p>${help}</p></div><div class="guide-card-grid">${items.map((x,i)=>`<button type="button" class="guide-choice" data-guide-preset="${kind}:${i}"><span aria-hidden="true">${x[2]&&x[2].length<3?x[2]:'+'}</span><strong>${esc(x[0])}</strong><small>${esc(x[1])}</small><b>Choose →</b></button>`).join('')}</div><p id="${kind}-feedback" class="save-note" role="status"></p></section>`;}
function systemChoices(){return quickCards('Which tools carry the work?','Choose a familiar system type, review the details below, then save. Nothing is assumed about its owner, quality or integration.',SYSTEM_STARTERS,'system');}
function systemVisualInventory(){const o=org();return `<section class="guided-system-map"><div class="section-head"><div><span class="eyebrow">YOUR INFORMATION LANDSCAPE</span><h2>${o.systems.length} systems, made visible.</h2></div><button class="button secondary" data-action="export-systems">Export CSV</button></div><div class="guide-card-grid">${o.systems.map((s,i)=>`<article class="guide-system-node"><span class="pill">${esc(s.integration)}</span><h3>${esc(s.name)}</h3><p>${esc(s.purpose)}</p><p><b>Owner:</b> ${esc(s.owner)}<br><b>Quality:</b> ${esc(s.quality)}<br><b>Access:</b> ${esc(s.access)}</p><div class="inline-actions"><button class="button small olive" data-edit-system="${i}">Edit</button><button class="text-button" data-delete="systems,${i}">Remove</button></div></article>`).join('')||'<div class="empty">Choose a card above or add your own system to start the landscape.</div>'}</div></section>`;}
const PRACTICE_CARDS=[
 ['No reliable source identified','Sources vary; checks are informal','Sources and checks defined; use varies','Sources maintained and checked consistently','Quality measured; recurring issues improved'],
 ['Practice not established','Work depends on individual workarounds','Practice documented; adherence varies','Practice followed; exceptions reviewed','Performance measured and practice improved'],
 ['Responsibility or capability missing','Informal support; depends on individuals','Roles and support defined; use varies','Roles supported and practice used consistently','Adoption measured and support improved'],
 ['Capability unavailable','Manual workarounds or isolated capability','Capability defined; reliability varies','Capability works consistently and is maintained','Performance monitored and capability improved'],
 ['Controls absent','Informal judgement and inconsistent controls','Rules defined; application varies','Rules applied; exceptions reviewed','Controls measured and improved'],
 ['Purpose or success measure absent','Individual ideas without common direction','Goals defined; ownership or use varies','Goals owned and reviewed consistently','Value measured and priorities adjusted']
];
function practiceScale(){const q=org().q||0,descriptions=PRACTICE_CARDS[Math.floor(q/4)],names=['Absent','Ad hoc','Defined','Consistent','Optimized'];return `<div class="practice-prompt"><span class="eyebrow">WHICH CARD BEST DESCRIBES YOUR OBSERVATION?</span><p>Apply these anchors to the statement above. Select “I don’t know yet” if you have not assessed it.</p></div><div class="scale practice-scale" role="group" aria-label="Observed practice rating">${descriptions.map((d,i)=>`<button data-answer="${i+1}" aria-pressed="${org().answers[q]===i+1}" class="${org().answers[q]===i+1?'selected':''}"><strong>${i+1}</strong><b>${names[i]}</b><span>${d}</span></button>`).join('')}</div>`;}
function guidedFill(formId,values){const form=document.getElementById(formId);if(!form)return false;for(const [k,v] of Object.entries(values)){const field=form.elements.namedItem(k);if(field)field.value=v;}form.scrollIntoView({behavior:window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});return true;}
function chooseGuidePreset(kind,index){
 let ok=false;
 if(kind==='system'&&SYSTEM_STARTERS[index]){const x=SYSTEM_STARTERS[index];ok=guidedFill('system-form',{name:x[0],purpose:x[1]});}
 if(kind==='truth'){const fields=['Forecast completion date','Project status','Benefits forecast','Accountable owner'];if(fields[index])ok=guidedFill('truth-form',{field:fields[index]});}
 if(kind==='outcome'&&OUTCOME_STARTERS[index]){const x=OUTCOME_STARTERS[index];ok=guidedFill('outcome-form',{metric:x[0],unit:x[1],direction:x[2]});}
 if(kind==='opportunity'){const names=['Draft a portfolio report','Route incoming requests','Validate required fields','Flag overdue updates'];if(names[index])ok=guidedFill('opportunity-form',{name:names[index]});}
 const feedback=document.getElementById(kind+'-feedback');if(feedback&&ok)feedback.textContent='Starting point selected. Review the form and your existing entries before saving; no record has been added yet.';return ok;
}
// Preserve every established route and data handler; guide the existing tools.
const guideOriginalHome=routes.home;
routes.home=()=>{const h=guideOriginalHome();const start=h.indexOf('<section class="hero');const end=h.indexOf('</section>',start);return start>=0?h.slice(0,start)+guideLanding()+h.slice(end+10):h;};
const guideOriginalSystems=routes.systems;
routes.systems=()=>{let h=guideOriginalSystems();h=h.replace('<div class="grid two">',systemChoices()+'<div class="grid two">');h=h.replace('<h3>Add a system</h3>','<h3>Review & save your system</h3>');const inventoryStart=h.indexOf('<section class="section"><div class="section-head"><h2>Your systems inventory.');if(inventoryStart>=0){const end=h.indexOf('</section>',inventoryStart);h=h.slice(0,inventoryStart)+systemVisualInventory()+h.slice(end+10);}h=h.replace('<form id="truth-form">',quickCards('Which record needs an owner?','Select a critical field, then identify its actual source, owner and reconciliation rule.',[['Forecast completion date','Where does the approved date live?'],['Project status','Which criteria determine the status?'],['Benefits forecast','Who maintains the value forecast?'],['Accountable owner','Who is responsible for the record?']],'truth')+'<form id="truth-form">');return h;};
const guideOriginalAssessment=routes.assessment;
routes.assessment=()=>guideOriginalAssessment().replace(/<div class="scale"[^>]*>[\s\S]*?<\/div>/,practiceScale());
const guideOriginalOpportunities=routes.opportunities;
routes.opportunities=()=>guideOriginalOpportunities().replace('<div class="grid two">',quickCards('What would you like to improve?','Pick an idea to name the opportunity. Rate its value, effort, risk and readiness using your own observations.',[['Draft a portfolio report','Reduce repeated report assembly'],['Route incoming requests','Clarify intake and assignment'],['Validate required fields','Find incomplete inputs'],['Flag overdue updates','Make freshness visible']],'opportunity')+'<div class="grid two">');
const guideOriginalOutcomes=routes.outcomes;
routes.outcomes=()=>guideOriginalOutcomes().replace('<div class="grid three outcome-types">',quickCards('Choose a measure that matters.','Pick a measure, then supply your real baseline, current observation, target and owner. No results are invented.',OUTCOME_STARTERS,'outcome')+'<div class="grid three outcome-types">');
// Dynamic legacy detail routes join the same map without removing their content.
for(let i=0;i<4;i++)routes['framework-'+i]=()=>framework(i);
for(let i=1;i<=3;i++)routes['tier-'+i]=()=>tierPage(i-1);
for(const [r,original] of Object.entries(routes)){
 if(r==='home')continue;
 routes[r]=()=>{let h=original();h=h.replace(/<nav class="journey-rail"[\s\S]*?<\/nav>/g,'').replace(/<aside class="next-bridge"[\s\S]*?<\/aside>/g,'');h=h.replace(/(<div class="wrap(?: article)?">)/,'$1'+guideRail(r));return insertBeforeWrapEnd(h,guideContinue(r));};
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.guideStop!==undefined){const i=+b.dataset.guideStop;if(!GUIDE_STATIONS[i])return;guideSelected=i;$('#guide-detail').innerHTML=guideDetail(i);$$('[data-guide-stop]').forEach(v=>{const selected=+v.dataset.guideStop===i;v.classList.toggle('is-selected',selected);v.setAttribute('aria-pressed',String(selected));});}if(b.dataset.guidePreset){const [kind,n]=b.dataset.guidePreset.split(':');chooseGuidePreset(kind,+n);}});
// Practical tutorials: authored guidance and per-workspace learning progress.
const TUTORIALS=[
 ['goal',0,'Define the problem before automating','journey',['Describe one workflow and its friction','Use the starter plan to identify observations','Choose a useful first investigation']],
 ['process',0,'Build your process map with task cards','process',['Choose tasks that reflect the real work','Arrange, edit and remove cards','Measure waiting, effort and rework']],
 ['systems',1,'Connect the tools behind your workflow','systems',['Choose system starter cards','Record actual ownership and capabilities','Edit and export your systems inventory']],
 ['sources',1,'Agree which information to trust','systems',['Select a critical field','Name its authoritative source and owner','Set update and reconciliation rules']],
 ['readiness',2,'Assess the six foundations before automating','assessment',['Separate data, process, people, tooling, governance and ambition','Choose observed-practice cards','Keep unknowns unscored and review gaps']],
 ['report',2,'Read your readiness results','report',['Interpret dimension scores','Inspect prerequisites and open gaps','Compare assessments with a consistent scope']],
 ['opportunities',2,'Choose an automation opportunity','opportunities',['Select a starting idea','Rate value, effort, readiness and risk','Compare candidates without treating rank as ROI']],
 ['roi',2,'Estimate value without overstating savings','roi',['Set effort and cost assumptions','Include setup and recurring costs','Distinguish capacity released from cash savings']],
 ['stress',3,'Test a messy portfolio before the pilot','stress-test',['Explore late vendors and stale updates','Compare intervention choices','Save the discovery and its next action']],
 ['governance',3,'Practice approvals in the governance canvas','canvas',['Route a simulated request','Review approval and escalation gates','Inspect the simulation log']],
 ['prompts',3,'Adapt prompts to a real workflow','prompts',['Choose a relevant prompt pattern','Add scope, sources and output requirements','Review outputs before operational use']],
 ['plan',4,'Turn findings into an implementation plan','implementation',['Prioritize foundation work','Define a bounded pilot','Review the 30/60/90-day checklist']],
 ['outcomes',4,'Measure what changed after the pilot','outcomes',['Choose an outcome measure','Record comparable baseline and current values','Review progress and reassess']],
 ['blueprints',4,'Choose the right implementation toolkit','pricing',['Compare the three available AI toolkits','Distinguish available products from previews','Understand what plans include and what deployment requires']],
 ['brief',4,'Prepare an executive decision brief','brief',['Summarize the current state','Connect findings to decisions and actions','Export a useful leadership briefing']],
 ['coe',4,'Build a PMO and change practice','coe',['Clarify mandate and services','Establish minimum reporting standards','Connect adoption to operational outcomes']],
 ['workspace',-1,'Save, back up and resume your work','workspace',['Use separate organization workspaces','Export and import a backup','Understand browser saving and its limits']],
 ['frameworks',-1,'Use the frameworks and resource library','frameworks',['Choose a framework for your question','Find a relevant template','Apply it within the discovery journey']]
];
function tutorialQuery(){return new URLSearchParams(viewHash().split('?')[1]||'');}
function tutorialBack(fallback='home'){const from=tutorialQuery().get('from');return from&&Object.hasOwn(routes,from)&&!from.startsWith('tutorial')?from:fallback;}
const LESSON_CONTENT={"goal": {"time": "8–12 min", "prepare": "Bring one recurring workflow and one recent example of where it became difficult.", "steps": [{"title": "Bound the problem", "body": "Use “Your problem” at the top of this lesson to name the work, the friction and the result you want. Keep the scope to one workflow, such as preparing a weekly report."}, {"title": "Generate a starting plan", "body": "Select “Build my starter plan”. Your suggested investigations appear immediately below the form, without leaving the lesson. The site uses local rules to suggest investigations. Read the result and decide which suggestions match the work; it has not inspected your organization or called an AI service."}, {"title": "Gather observations", "body": "Follow one recent case from its trigger to its final output. Ask the person doing the work where they wait, copy information or seek clarification. Separate observed delays from suspected causes."}, {"title": "Carry the question into the map", "body": "Select “Next: build your process map” beneath your starter plan for the next lesson, or go straight to the process builder. Your saved problem is available there when you have not already entered a different process problem. Use the same workflow name and assign an accountable process owner. Map what happens today before proposing automation."}], "example": "Problem: “Preparing the weekly portfolio report takes three days.” Scope: updates requested Monday through approved report Wednesday. First investigation: trace one report and record how long the team waits for missing updates.", "pitfall": "“We need AI” names a solution before the problem is understood. A useful goal identifies the work and a measurable friction.", "question": "What should you do if the suggested plan does not describe your work?", "answer": "Use it only as a starting point. Retain relevant investigations and map the actual work; suggestions are not verified findings.", "checks": ["I named one workflow and its boundaries", "I identified a real case to inspect", "I chose the first investigation and an owner"]}, "process": {"time": "15–20 min", "prepare": "Have a recent workflow example and the roles involved. Timings can remain unmeasured until observed.", "steps": [{"title": "Name the work", "body": "Enter the issue in “Your problem or workflow” and select “Suggest tasks”. Fill in “Process name” and “Accountable process owner”. Choose a Task collection if the suggestions need a different starting point."}, {"title": "Build the current sequence", "body": "Select suggested cards that actually occur. Use “+ Add a custom task” for missing activities. Include the request, preparation, checks, decisions and final handoff. New suggestions do not replace existing cards."}, {"title": "Refine each handoff", "body": "Use “Earlier” and “Later” to arrange cards. Select “Edit details” to record the responsible role, system and task details. Use “Remove” for a task that does not belong. A decision card identifies a review point; the map remains sequential."}, {"title": "Measure and export", "body": "Record active effort as touch time and idle delay as waiting time, both in minutes. Record observed rework rather than guessing. Review the process signals, then choose “Export CSV” or “Print / Save PDF”. Totals include measured tasks only."}], "example": "Illustrative sequence: Request updates → Collect responses → Reconcile conflicts → Review draft → Publish report. One review takes 15 minutes of work after 120 minutes waiting: record touch 15 and wait 120. Its elapsed contribution is 135 minutes.", "pitfall": "Do not enter zero for unknown timing. Do not sum parallel activities as though they were a sequential critical path.", "question": "A map contains six tasks but only two have timings. Is the displayed elapsed time the full process duration?", "answer": "No. It is the sum of recorded timings for measured tasks. Measure the remaining steps before describing total duration.", "checks": ["I mapped the actual sequence and owner", "I reviewed task details and unmeasured steps", "I identified one delay to investigate"]}, "systems": {"time": "12–15 min", "prepare": "Keep your process map nearby and list the applications or files used at each step.", "steps": [{"title": "Choose a starter", "body": "Open Systems and choose a familiar system card, such as “Spreadsheet / tracker”. A card fills a starting name and purpose; it does not save a record or establish its quality."}, {"title": "Replace generic details", "body": "Under “Review & save your system”, enter the actual system name, owner or team, and purpose or records held. Identify the record used by the workflow, not merely the vendor name."}, {"title": "Record observed capabilities", "body": "Review Integration, Data quality, Data sensitivity and Access controls. Select what you have checked. A connector being available does not mean this workflow uses it, and unknown quality should remain Unknown."}, {"title": "Save and review dependencies", "body": "Select “Add system”. Inspect the visual inventory; use “Edit” to correct details or “Remove” for an incorrect entry. Export CSV for a team review. Continue to source ownership for critical fields."}], "example": "Illustrative record: Portfolio tracker; owner: PMO analyst; purpose: milestone dates and project status; integration: File export / import; quality: Unknown until sampled; access: Not reviewed until confirmed.", "pitfall": "A technically integrated system can still contain stale or disputed information. Check capability and information quality separately.", "question": "Does selecting a system starter card create a saved system?", "answer": "No. Review the populated form and select Add system to create the inventory record.", "checks": ["I listed the systems behind my map", "I verified or marked unknown the key capabilities", "I reviewed saved owners and records"]}, "sources": {"time": "12–15 min", "prepare": "Choose one field whose value affects a decision, such as the forecast completion date.", "steps": [{"title": "Choose the critical field", "body": "In Systems, find “Which source can you trust?” and select a field card or enter your own Critical field / record. Work field by field: one system need not be authoritative for everything."}, {"title": "Identify authority and upkeep", "body": "Enter the Authoritative source, Accountable role, and Update cadence / cutoff. Name the source the team agrees to use and the role that maintains it. Confirm this agreement with the people involved."}, {"title": "Resolve disagreement explicitly", "body": "In “Rule when sources disagree”, describe who reconciles the values, what evidence they inspect and where the decision is recorded. Select “Save source ownership”. To replace an incorrect source entry, remove that record and save a corrected one."}, {"title": "Assess update behaviour", "body": "Use “Observed update behaviour” to record actual maintenance discipline. Leave it unknown if unassessed. Ownership on paper and consistent updates in practice are separate findings."}], "example": "Field: forecast completion date. Source: approved portfolio register. Owner: project lead. Cutoff: Friday noon. Rule: project lead reconciles conflicting dates against the approved schedule and records the reason for any change in the register.", "pitfall": "“Use the latest file” is not enough when timestamps differ from approval dates. Agree authority and a reconciliation rule.", "question": "An API refreshes every hour, but project leads have not updated dates for a month. Is the information current?", "answer": "No. Transfer frequency does not establish source freshness. Investigate update discipline and make stale records visible.", "checks": ["I named a critical field and its authoritative source", "I recorded owner, cutoff and reconciliation rule", "I assessed update behaviour separately"]}, "readiness": {"time": "20–30 min", "prepare": "Use one workflow scope and recent observations from people doing the work.", "steps": [{"title": "Keep one scope", "body": "Open the assessment for the correct workspace. Answer all 24 statements for the same workflow. The six dimensions are Data, Process, People, Tooling, Governance and Ambition."}, {"title": "Choose an observed-practice card", "body": "For each statement, choose 1 Absent, 2 Ad hoc, 3 Defined, 4 Consistent or 5 Optimized. The card describes maturity of that practice. Documented instructions alone do not demonstrate consistent use."}, {"title": "Preserve uncertainty", "body": "Add a short Observation and Confidence when helpful. Select “I don’t know yet” when you have not investigated a statement. It becomes a discovery gap and remains unrated, rather than receiving a low score."}, {"title": "Close gaps before comparison", "body": "Revisit unknown questions after investigation. All 24 answers are needed for a complete score. Review the report and record the scope and observation period when comparing later assessments."}], "example": "A team has an approved procedure, but three of five sampled cases used workarounds. “Defined” may fit better than “Consistent”. Observation: “Procedure exists; sampled adherence varies.” The sample informs discussion; it is not an audit conclusion.", "pitfall": "Do not reward sophisticated software with higher scores for data, people or governance. Each dimension asks a different question.", "question": "What rating should you choose when you do not know whether a control operates?", "answer": "Select I don’t know yet. Investigate the control instead of assigning either 1 or 5.", "checks": ["I used one consistent scope", "I recorded observations and preserved unknowns", "I reviewed all six dimensions and remaining gaps"]}, "report": {"time": "10–15 min", "prepare": "Complete an assessment or inspect the report to see which baseline information is still missing.", "steps": [{"title": "Read the dimensions first", "body": "Open the readiness report. Compare the six dimension scores and identify the weak foundations. The overall result is an equal-weight summary, so it can hide a weak individual area."}, {"title": "Interpret the calculation", "body": "Each dimension normalizes the mean of four 1–5 answers to 0–100. All 1s produce 0; all 5s produce 100. The overall result averages the six rounded dimension scores. Use Methodology for the full rule."}, {"title": "Review prerequisites separately", "body": "Inspect the automated portfolio-reporting example prerequisites. Process ownership, source authority, update discipline and scenario review are planning checks alongside the score. A recorded check is not independent verification."}, {"title": "Turn one gap into action", "body": "Choose a weak area, assign someone to investigate it and return to the relevant tool. Compare future assessments only with consistent scope and evidence. Use outcomes to measure operational improvement separately."}], "example": "If a dimension has ratings 3, 3, 3 and 3, its score is 50. A higher overall score does not remove a governance gap; the site recommends foundation work when Data, Process or Governance is below 60.", "pitfall": "The readiness score is a self-assessment planning heuristic, not a certificate or proof that a deployment will succeed.", "question": "Does a higher readiness score prove the workflow saved time?", "answer": "No. Measure time, quality and other outcomes directly. Readiness describes self-assessed practices.", "checks": ["I reviewed dimension scores rather than only the total", "I inspected outstanding prerequisites", "I assigned a next action for one gap"]}, "opportunities": {"time": "12–18 min", "prepare": "Bring at least two improvement ideas grounded in your map and systems inventory.", "steps": [{"title": "Name one bounded opportunity", "body": "Choose a starter such as “Draft a portfolio report” or type a specific workflow. Keep separate ideas as separate candidates so their ratings can be compared."}, {"title": "Rate the four factors", "body": "Review Business value, Foundation readiness, Implementation effort and Business / data risk on the 1–5 scales. High value and readiness help priority; high effort and risk reduce it. The default 3 values are starting values, not findings."}, {"title": "Save and compare", "body": "Select “Add opportunity”. Review the portfolio and its labels. Risk 4–5 calls for governance review; readiness 1–2 calls for foundation work, even when the numeric priority is attractive."}, {"title": "Investigate before choosing", "body": "Discuss the assumptions with the owner and use “Model the value” for a cost scenario. To correct an opportunity in this version, remove it and add the revised ratings. Keep the rationale in your project notes."}], "example": "Illustrative ratings: value 4, readiness 3, effort 2, risk 2. Priority = [8 + 3 + 4 + 4] / 25 × 100 = 76. This score helps compare candidates; it is not a 76% success probability.", "pitfall": "An attractive ranking does not override a required approval or unresolved prerequisite.", "question": "What should happen to a high-priority opportunity with risk rated 5?", "answer": "Send it for governance review and address controls before a pilot decision.", "checks": ["I compared at least two bounded ideas", "I replaced default ratings with considered estimates", "I reviewed risk and foundation flags"]}, "roi": {"time": "15–20 min", "prepare": "Have estimates for repetitive effort, loaded hourly cost, setup cost and recurring cost. The calculator uses USD.", "steps": [{"title": "Set the effort baseline", "body": "Use the sliders for People involved and Repetitive hours / person / week. Count the targeted repetitive work only; avoid counting the same shared task once for each team member."}, {"title": "Estimate a realistic reduction", "body": "Set Potential time reduction and Working weeks / year. Include time needed for review and exception handling when estimating the reduction. Use Loaded hourly cost consistently."}, {"title": "Include delivery and running costs", "body": "Set Implementation cost and Recurring cost / month. Include the applicable configuration, training, licensing and support costs in those estimates. The model does not automatically discover hidden costs."}, {"title": "Compare scenarios", "body": "Review the output, then lower the time-reduction assumption and compare the result. Select “Export scenario” for each version you want to retain; the sliders hold the current scenario. Treat estimated released capacity separately from cash savings."}], "example": "Illustrative scenario: 4 people × 5 hours × 40% = 8 hours released weekly. At 48 weeks and $50/hour, gross annual capacity value is $19,200. With $300/month recurring cost, net annual value is $15,600. A $6,000 setup cost gives about 4.6 months modeled payback.", "pitfall": "Payback assumes steady modeled benefits. The model does not schedule a gradual rollout or guarantee that released hours reduce payroll.", "question": "If staff use released time to improve service, is all capacity value cash saved?", "answer": "No. It may be valuable capacity redeployed. Cash savings require an actual reduction in expenditure.", "checks": ["I checked effort and cost assumptions", "I compared a more conservative scenario", "I distinguished capacity value from cash savings"]}, "stress": {"time": "15–20 min", "prepare": "Bring your process and source rules. The three scenarios use fictional portfolio situations.", "steps": [{"title": "Start with a failure situation", "body": "Open Portfolio challenges and choose “The late vendor”, “The disputed status” or “The reluctant updater”. Read the situation and question before choosing a response."}, {"title": "Try an intervention", "body": "Select the response you would take. Read the feedback and its explanation of the underlying operating gap. Try an alternative to see why a seemingly convenient response may leave the problem unresolved."}, {"title": "Save the lesson", "body": "Select “Save this discovery” after reviewing the response. The workspace records the scenario review and its suggested action. Reviewing a scenario does not establish that your team already follows the practice."}, {"title": "Apply and repeat", "body": "Review all three scenarios. Carry the action into your map or source rules: dependency ownership, evidence for status overrides, and visibility of stale updates. Agree the operational change with the relevant owner."}], "example": "For a stale update, do not assume unchanged status means healthy progress. Identify the update owner, agree the cutoff and make missing or stale evidence visible so the reviewer can investigate.", "pitfall": "The exercise teaches reasoning. A saved scenario is not a live test of your actual workflow or its production controls.", "question": "A sponsor requests a green status despite evidence of delay. What should remain visible?", "answer": "The agreed criteria, underlying evidence, authorized decision and any recorded override or unresolved disagreement.", "checks": ["I explored all three scenarios", "I saved the discoveries after reading feedback", "I identified a rule to apply to my workflow"]}, "governance": {"time": "12–15 min", "prepare": "Use fictional requests. This is a local keyword-routing simulation, with no model calls or external actions.", "steps": [{"title": "Run a low-impact sample", "body": "Open Governance Canvas and choose “Diagnostic”, then run the request if needed. Read the console to see routing and the participating agents. Agent labels demonstrate roles, not independently running AI services."}, {"title": "Inspect approval behaviour", "body": "Choose “High-risk action” or enter the sample request to send a customer email. Review the pending decision. Try “Reject”, then run it again and try “Approve simulation”. Neither action sends an email."}, {"title": "Inspect escalation", "body": "Choose “Critical action”. Read the review requirement and use “Simulate escalation”. This demo does not verify identity or execute a production infrastructure action."}, {"title": "Keep the learning", "body": "Use “Download session log” before reloading or resetting the session. Decide which real roles would review, approve or escalate each action in your workflow. Record those requirements in the implementation plan."}], "example": "An AI-drafted customer email may be prepared automatically while an accountable human checks recipient, accuracy and tone before sending. In a real implementation, the send permission and approval record must be enforced outside this simulation.", "pitfall": "Keyword routing is not a production security classifier. Passing this demo does not validate a real approval system.", "question": "What changes outside the site when you select Approve simulation?", "answer": "Nothing. It records a simulated decision only; no message is sent and no external system is changed.", "checks": ["I tried routing, rejection and simulated approval", "I reviewed the critical-action escalation path", "I identified real approval roles and kept useful session notes"]}, "prompts": {"time": "15–20 min", "prepare": "Choose one bounded drafting or analysis task and use fictional or appropriately approved sample inputs.", "steps": [{"title": "Choose a pattern", "body": "Open the Prompt library and select a prompt relevant to the task. Read it before copying. Define the exact output you want, such as an exception summary for human review."}, {"title": "Add scope and sources", "body": "Adapt the prompt with the workflow scope, allowed source material, definitions and any cutoff date. Tell the model how to handle missing or conflicting information instead of asking it to fill gaps."}, {"title": "Specify the reviewable output", "body": "Ask for a structure that supports checking: finding, source reference, uncertainty and proposed next action. Require the model to distinguish a source fact from an inference. Use a separate approved AI environment if you want to run the prompt; this library does not execute it."}, {"title": "Test and revise", "body": "Try a normal case, a missing-input case and a conflicting-input case. Check statements against the source, correct the prompt and repeat. Keep a human review step before using the output operationally."}], "example": "Example prompt: “Using only the supplied fictional milestone table, list overdue items as project, due date, source row and missing information. Do not invent dates or infer progress from blank fields. Flag conflicts for review. Produce a draft for the portfolio analyst; do not send messages or change records.”", "pitfall": "A request for citations does not ensure those citations are correct. Open the referenced input and check the claim.", "question": "What should the prompt do when an essential date is missing?", "answer": "Flag the missing date and request review rather than inventing a value or silently assuming the project is on track.", "checks": ["I adapted a prompt to one bounded task", "I specified sources, missing-data behaviour and output", "I tested an exception and reviewed the result"]}, "plan": {"time": "20–30 min", "prepare": "Bring the assessment gaps, selected opportunity, source rules and baseline measures.", "steps": [{"title": "Assess and simplify", "body": "Open the implementation checklist. In Days 1–30, complete the baseline, map, inventory and ownership tasks. Remove redundant steps before automating them. Check a box only after doing the action."}, {"title": "Define the pilot", "body": "For Days 31–60, select one opportunity and agree acceptance criteria. Name the pilot users, input boundary, reviewer, fallback and stop conditions in your project plan. Use the site checklist to track the corresponding actions."}, {"title": "Test and measure", "body": "Use representative inputs plus missing, duplicate and conflicting records. Exercise review and manual fallback. Measure effort, quality and recurring cost; preserve the baseline so the comparison is meaningful."}, {"title": "Review before expanding", "body": "In Days 61–90, compare observations, review incidents and adoption, update procedures and prepare a decision. Choose “Print your plan” for the current checklist. Reassess before widening scope; the day ranges are a planning structure, not automatic deadlines."}], "example": "Example pilot boundary: draft the weekly report for three projects over two reporting cycles. Analyst reviews every draft; no automatic distribution. Example stop condition: an unsupported status claim reaches the review output. Agree measurable acceptance criteria with the owner before starting.", "pitfall": "A completed checklist describes recorded actions. It does not deploy software, provision integrations or independently verify acceptance.", "question": "What should happen when a pilot misses an agreed quality criterion?", "answer": "Investigate, adjust or stop under the agreed review rules. Do not expand scope merely because the planned date has arrived.", "checks": ["I identified prerequisite work and owners", "I defined pilot acceptance and fallback arrangements", "I set a review point before expansion"]}, "outcomes": {"time": "12–18 min", "prepare": "Bring a measured baseline and a comparable current observation from the same workflow.", "steps": [{"title": "Choose the measure", "body": "Open Outcome tracking and choose a starter such as Reporting effort or Decision delay. The card fills a starting metric, unit and direction; review the form before saving."}, {"title": "Define comparable values", "body": "Enter Metric, Unit, Accountable role, Baseline, Current observation and Target. Use the same time period, population and measurement method. Pick whether lower or higher is better."}, {"title": "Save and interpret", "body": "Select “Save outcome measure”. Read the baseline-current-target comparison. The displayed percentage measures progress toward your target change, not the percentage improvement from baseline."}, {"title": "Return after another cycle", "body": "Use “Update observation” for a new current value. Keep detailed period-by-period evidence separately: this tool updates the current observation rather than maintaining a full measurement time series. Reassess the process alongside the result."}], "example": "Baseline 10 hours, current 8 hours, target 6 hours: 2 of the planned 4 hours have been recovered, so target progress is 50%. The reduction from baseline is 20%. Both are valid but answer different questions.", "pitfall": "A smaller workload can reduce effort without any automation benefit. Compare equivalent periods and document other changes.", "question": "Is 50% of target change the same as a 50% reduction in effort?", "answer": "No. In the 10 → 8 → 6 hour example, target progress is 50% while the effort reduction is 20%.", "checks": ["I recorded comparable values and a responsible role", "I understood target progress versus baseline change", "I set the next observation date in my working plan"]}, "blueprints": {"time": "8–12 min", "prepare": "Identify the support you need from your discovery findings before comparing products.", "steps": [{"title": "Start with the gap", "body": "Review Recommended next steps and your findings. Decide whether the immediate need is workflow consistency, governance or a broader transformation approach. Free tools can support investigation before a purchase."}, {"title": "Compare the available toolkits", "body": "Open Available blueprints and review the product detail pages for Workflow Standardization Kit, Governance & Risk Framework and Complete Transformation System. Compare the listed contents with the gap you are trying to close."}, {"title": "Separate products from previews", "body": "Read availability labels. Discovery and PMO previews are separate from the three existing purchasable AI toolkits. Do not assume a preview is included in an existing product or available to purchase."}, {"title": "Plan implementation effort", "body": "Treat a guide or toolkit as planning support. Identify who will configure the workflow, test it, approve it and operate it, with any separate software or delivery costs. Follow a checkout link only after reviewing the current product details."}], "example": "If unclear handoffs are the problem, standardization support may be relevant. If the main gap is approval authority, review governance support. A broader transformation guide fits a broader planning need, not simply a desire for the largest package.", "pitfall": "Buying a deployment plan does not mean an AI workflow has been installed, integrated or operated for you.", "question": "Does purchasing a toolkit complete the implementation checklist?", "answer": "No. The buyer or their delivery team still needs to apply the guidance, configure, test, govern and measure the implementation.", "checks": ["I connected a product need to a specific gap", "I checked included contents and availability", "I identified implementation work and separate costs"]}, "brief": {"time": "12–15 min", "prepare": "Check that the intended workspace is active and its saved information is current.", "steps": [{"title": "Review source records", "body": "Check the latest assessment, process name, mapped steps, systems and opportunities. The executive brief derives its summary from saved workspace records; it does not independently validate them."}, {"title": "Read the generated brief", "body": "Open Executive brief. Check The situation and Priority constraints against your records. If the baseline is missing, complete it or retain the visible limitation rather than presenting an invented score."}, {"title": "Prepare the actual decision", "body": "Use Recommended decision and Measures of success as a starting point. In your accompanying leadership notes, specify the requested decision, owner, budget assumptions, acceptance criteria and review date. This page is a generated brief, not a free-text document editor."}, {"title": "Export and review", "body": "Choose “Print / Save PDF”. Inspect the print preview and saved document before sharing. Update the underlying workspace and regenerate when a source fact changes."}], "example": "Example accompanying decision: “Authorize a two-cycle, read-only reporting pilot for three projects, with analyst review of every draft. Review effort and unsupported claims before expansion.” Keep estimated costs and unresolved gaps visible.", "pitfall": "A generic recommended decision should be reviewed for the real authority, scope and funding required.", "question": "Where should you correct an incorrect process name appearing in the brief?", "answer": "Correct the process name in the process builder, then reopen the generated brief.", "checks": ["I checked the source records and scope", "I prepared a concrete decision request", "I reviewed the exported brief"]}, "coe": {"time": "25–35 min", "prepare": "Bring a portfolio reporting pain point and the people who use the resulting decisions.", "steps": [{"title": "Clarify the mandate", "body": "Open PMO & Change COE. Follow “Clarify the mandate”: identify the sponsor, the decisions the COE supports, its customers, services and authority. Record the agreement in your team charter."}, {"title": "Trace actual reporting", "body": "Use “Map the reporting process” and inspect contrasting projects, including a troubled one. Follow how an update becomes a portfolio report and where interpretation or ownership changes."}, {"title": "Agree minimum standards", "body": "Use “Establish source ownership”. Define essential fields, status criteria, source owners, cutoffs and escalation rules. Keep useful local variation where it does not undermine common decisions."}, {"title": "Pilot with adoption in view", "body": "Choose one administrative task. Use “Set outcome measures” for effort and decision usefulness. Ask why updates are difficult: capacity, unclear expectations and incentives may matter as much as training. Review scenarios with practitioners before scaling."}], "example": "Example minimum service: publish a weekly exception view with source dates and named owners. A green status requires agreed criteria and current evidence; stale entries are visibly unresolved. The COE supports the decision without silently changing project ownership.", "pitfall": "A new reporting platform does not by itself create a mandate, trustworthy updates or adoption.", "question": "What should the COE define before choosing a new tool?", "answer": "Its mandate, customers, decision needs, authority and minimum operating practices.", "checks": ["I drafted the mandate and decision needs", "I traced reporting and minimum standards", "I defined a pilot and adoption measures"]}, "workspace": {"time": "8–12 min", "prepare": "Use the same browser and site address where your work was recorded.", "steps": [{"title": "Check the active organization", "body": "Open My workspace and confirm the organization selector before editing. Client workspaces let you keep separate organizations in this browser; they are not separate authenticated team portals."}, {"title": "Understand saving", "body": "Saved work uses this browser’s local storage. The tutorial checklists also belong to the active organization. Reloading normally retains saved data, but another device or site address has its own storage."}, {"title": "Export a backup", "body": "Select “Export backup” from the workspace and keep the downloaded JSON in an appropriate location. The backup includes all workspaces, so check its scope before sharing. Export before clearing browser data or moving devices."}, {"title": "Restore and verify", "body": "On the destination, choose “Import backup” and select the JSON. Imported organizations are added as separate copies; existing work is retained. Select the intended imported workspace and inspect its records. Avoid repeated imports that create unnecessary copies."}], "example": "Example move: export on your laptop, transfer the JSON securely, open the site on your desktop and import. Select the imported organization and inspect a known process step and tutorial checkbox before continuing.", "pitfall": "There is no account-based cloud sync. Browser storage and exports need appropriate handling when they contain client information.", "question": "Will signing into the browser automatically synchronize this site’s workspace?", "answer": "No. Use Export backup and Import backup to move the saved site records.", "checks": ["I confirmed the active organization", "I exported a backup of current work", "I understand how to restore and select the intended copy"]}, "frameworks": {"time": "12–18 min", "prepare": "Bring a concrete question from your map, assessment or implementation plan.", "steps": [{"title": "Start with the question", "body": "Open Frameworks. Read the four framework descriptions and select the one that addresses your question. Use the framework to organize a decision or investigation, rather than treating every section as mandatory."}, {"title": "Connect it to your evidence", "body": "Read the selected framework and relate each useful element to an observed process, source, role or control. Mark unanswered items as work to investigate. Do not replace missing evidence with polished wording."}, {"title": "Use a supporting resource", "body": "Open Resources & templates from the explorer map. Review the available template or reference before using it. Populate it with your own scope, evidence and owners in your working document; return to the relevant site tool to record supported findings."}, {"title": "Close the loop", "body": "Use the prompt library for drafting support where useful, then verify the output. Carry decisions into the implementation checklist and define an outcome measure. Revisit the framework when the work changes."}], "example": "Question: “Who should approve an automated report before release?” Use the relevant governance material to specify the reviewer, approval conditions, exception route and retained record. Check those requirements against the process map and pilot plan.", "pitfall": "Completing a template is not evidence that the described practice is operating. Confirm the practice with the people doing the work.", "question": "What makes a framework useful in this journey?", "answer": "It helps answer a specific question and produces an actionable decision grounded in observed work.", "checks": ["I chose a framework for a specific question", "I connected it to evidence and unresolved gaps", "I carried one action into my plan"]}};
function tutorialProgress(id){const v=org().tutorialProgress?.[id];return Array.isArray(v)?[...new Set(v.filter(n=>Number.isInteger(n)&&n>=0&&n<LESSON_CONTENT[id].checks.length))]:[];}
function tutorialComplete(t){return LESSON_CONTENT[t[0]].checks.every((_,i)=>tutorialProgress(t[0]).includes(i));}
function tutorialCard(t){const l=LESSON_CONTENT[t[0]],done=tutorialComplete(t);return `<article class="card tutorial-card"><div class="tutorial-cover" aria-hidden="true"><span>${t[1]>=0?GUIDE_STATIONS[t[1]].icon:'▤'}</span><small>BEFORE YOU AUTOMATE</small><b>${t[1]>=0?'STAGE '+(t[1]+1):'WORKSPACE ESSENTIALS'}</b></div><span class="pill">${done?'✓ Checklist complete':'Practical tutorial'} · ${l.time}</span><h3>${t[2]}</h3><p>${t[4][0]}.</p><div class="actions">${link('tutorial-'+t[0]+'?from='+encodeURIComponent(tutorialBack(t[3])),done?'Revisit tutorial':'Start tutorial','button small secondary')}${link(t[3],'Open the tool','link')}</div></article>`;}
function tutorialHub(){const q=tutorialQuery(),raw=q.get('stage'),stage=/^[0-4]$/.test(raw||'')?+raw:null;const items=TUTORIALS.filter(t=>stage===null||t[1]===stage),back=tutorialBack();return `<div class="wrap">${guideRail(stage===null?'tutorials':GUIDE_STATIONS[stage].route)}${head('LEARN / BEFORE YOU AUTOMATE','A little guidance.<br><span class="accent">A clearer next step.</span>','Practical written walkthroughs for every stage. Learn the method, try it in your tool, then check off what you have completed.')}<div class="tutorial-banner"><div><span class="eyebrow">YOUR LEARNING PATH · ${esc(org().name)}</span><h3>${stage===null?'Follow the journey, one lesson at a time.':'Lessons for stage '+(stage+1)+': '+GUIDE_STATIONS[stage].title}</h3><p>${TUTORIALS.filter(tutorialComplete).length} of ${TUTORIALS.length} lesson checklists complete. Progress saves in this workspace and travels with your backup.</p></div>${link(back,'← Return to my work','button secondary')}</div><nav class="tutorial-filters" aria-label="Filter lessons by stage">${[['all','All lessons'],...GUIDE_STATIONS.map((s,i)=>[String(i),(i+1)+'. '+s.title])].map(([v,l])=>`<a class="${stage===null&&v==='all'||String(stage)===v?'selected':''}" href="#/tutorials${v==='all'?'?':'?stage='+v+'&'}from=${encodeURIComponent(back)}" ${stage===null&&v==='all'||String(stage)===v?'aria-current="page"':''}>${l}</a>`).join('')}</nav><p class="muted">${items.length} tutorials · Suggested practice times · All lessons free</p><div class="grid three">${items.map(tutorialCard).join('')}</div><div class="guide-return">${link('home','Explore the full journey map','button secondary')}${link(back,'Return to my work','button olive')}</div></div>`;}
function goalLessonResult(value){
 const plan=discoveryGoalPlan(value);if(!plan)return '<p class="save-note">Your starter plan will appear here after you describe the problem.</p>';
 return `<section class="lesson-example"><span class="eyebrow">YOUR PROBLEM → YOUR NEXT ACTIONS</span><h2>${esc(plan.title)}</h2><p><b>Problem to investigate:</b> ${esc(plan.goal)}</p><ol>${plan.checks.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>${esc(plan.metric)}</p><p class="save-note">These are suggested investigations based on your wording, not verified findings.</p><div class="actions">${link('tutorial-process?from=process','Next: build your process map','button lime')}${link('process?lesson=goal','Go straight to the process builder','button secondary')}</div></section>`;
}
function goalLessonExercise(){const d=discovery();return `<section class="card goal-lesson-exercise" aria-labelledby="goal-exercise-title"><span class="eyebrow">STEP 1 / TRY IT HERE</span><h2 id="goal-exercise-title">What is making the work difficult?</h2><p>Name one recurring task and what gets in the way. For example: “Preparing our weekly report takes three days because updates arrive late.”</p><form id="goal-lesson-form"><label for="goal-lesson-input">Your problem<textarea id="goal-lesson-input" name="goal" required minlength="3" maxlength="300" rows="3" placeholder="What work is difficult, and why?">${esc(d.goalLessonDraft??d.goal??'')}</textarea></label><div class="actions"><button class="button olive" type="button" data-build-goal>Build my starter plan</button><button class="button secondary" type="button" data-goal-example>Try the reporting example</button></div></form><p class="save-note">Work directly in this lesson. Your current browser workspace is used automatically; no setup is needed. The example only fills the field until you build the plan.</p><p id="goal-lesson-status" role="status"></p><div id="goal-lesson-result" role="region" aria-label="Your practical starter plan" aria-live="polite">${goalLessonResult(d.goal)}</div></section>`;}
document.addEventListener('input',e=>{if(e.target.id==='goal-lesson-input'){discovery().goalLessonDraft=e.target.value;save();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.dataset.goalExample===undefined)return;const input=document.getElementById('goal-lesson-input');input.value='Preparing our weekly portfolio report takes three days because updates arrive late.';discovery().goalLessonDraft=input.value;save();input.focus();});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.buildGoal===undefined)return;document.getElementById('goal-lesson-form').dispatchEvent(new Event('submit',{bubbles:true,cancelable:true}));});
document.addEventListener('submit',e=>{if(e.target.id!=='goal-lesson-form')return;e.preventDefault();const input=document.getElementById('goal-lesson-input'),value=input.value.trim();if(value.length<3){input.setCustomValidity('Describe the problem using at least three characters.');input.reportValidity();input.setCustomValidity('');return;}const d=discovery();d.goal=value;d.goalLessonDraft=value;save();document.getElementById('goal-lesson-result').innerHTML=goalLessonResult(value);document.getElementById('goal-lesson-status').textContent=saveFailed?'Your plan is ready below. Browser saving is unavailable; export a backup to keep it.':'Your plan is ready below and saved. Next, map the tasks behind this problem.';});
function tutorialLesson(t){const l=LESSON_CONTENT[t[0]],back=tutorialBack(t[3]),n=TUTORIALS.indexOf(t),next=TUTORIALS[n+1];return `<div class="wrap">${t[0]==='goal'?'<nav aria-label="Tutorial navigation">'+link('tutorials','← All tutorials','guide-text-link')+'</nav>':guideRail(t[1]>=0?GUIDE_STATIONS[t[1]].route:'tutorials')}${head('PRACTICAL TUTORIAL / '+l.time.toUpperCase(),t[2],'Read → try in the tool → check your work. Examples are illustrative; use your own observations for real records.')}${t[0]==='goal'?goalLessonExercise():`<div class="lesson-start"><div><span class="eyebrow">BEFORE YOU START</span><p>${esc(l.prepare)}</p></div>${link(t[3],'Open the tool','button olive')}</div>`}<div class="lesson-layout"><article><h2>Make it practical.</h2><ol class="lesson-steps">${l.steps.map((x,i)=>`<li><span class="lesson-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p></div></li>`).join('')}</ol><section class="lesson-example"><span class="eyebrow">WORKED EXAMPLE</span><h2>See it in context.</h2><p>${esc(l.example)}</p></section><section class="card lesson-check"><span class="eyebrow">CHECK YOUR UNDERSTANDING</span><h3>${esc(l.question)}</h3><details><summary>Reveal the explanation</summary><p>${esc(l.answer)}</p></details></section></article><aside class="lesson-sidebar"><section class="card"><span class="eyebrow">YOUR TAKEAWAYS</span><ul class="tutorial-outline">${t[4].map(x=>`<li>${esc(x)}</li>`).join('')}</ul></section><section class="card lesson-pitfall"><span class="eyebrow">COMMON MISTAKE</span><p>${esc(l.pitfall)}</p></section><section class="card"><span class="eyebrow">PUT IT INTO PRACTICE</span><h2>My completion checklist</h2>${l.checks.map((x,i)=>`<label class="checkline"><input type="checkbox" data-tutorial-check="${t[0]}:${i}" ${tutorialProgress(t[0]).includes(i)?'checked':''}><span>${esc(x)}</span></label>`).join('')}<p id="lesson-progress" role="status">${tutorialProgress(t[0]).length} / ${l.checks.length} actions checked</p><p class="save-note">Saved for ${esc(org().name)} in this browser. Learning progress is separate from readiness scores and operational results.</p></section></aside></div><div class="guide-return">${link(t[0]==='goal'?'tutorials':back,t[0]==='goal'?'← All tutorials':'← Return to my work','button secondary')}${link('tutorials'+(t[1]>=0?'?stage='+t[1]+'&':'?')+'from='+encodeURIComponent(back),'Browse related lessons','button secondary')}${next?link('tutorial-'+next[0]+'?from='+encodeURIComponent(back),'Next lesson: '+next[2],'button olive'):link('tutorials','Review my learning progress','button olive')}</div></div>`;}
document.addEventListener('change',e=>{const raw=e.target.dataset.tutorialCheck;if(!raw)return;const [id,v]=raw.split(':'),i=Number(v),l=LESSON_CONTENT[id];if(!l||!Number.isInteger(i)||i<0||i>=l.checks.length)return;const o=org();o.tutorialProgress=o.tutorialProgress||{};const current=tutorialProgress(id).filter(n=>n!==i);if(e.target.checked)current.push(i);o.tutorialProgress[id]=current;save();const status=document.getElementById('lesson-progress');if(status)status.textContent=current.length+' / '+l.checks.length+' actions checked'+(saveFailed?' · Export a backup to keep your progress.':' · Saved');});
routes.tutorials=tutorialHub;
for(const t of TUTORIALS)routes['tutorial-'+t[0]]=()=>tutorialLesson(t);
const TUTORIAL_CONTEXT={journey:'goal',process:'process',systems:'systems',assessment:'readiness',report:'report','report-preview':'report',opportunities:'opportunities',roi:'roi','roi-calculator':'roi','stress-test':'stress',canvas:'governance',prompts:'prompts',implementation:'plan','implementation-guide':'plan',outcomes:'outcomes',pricing:'blueprints',recommendations:'blueprints',brief:'brief','executive-brief':'brief',coe:'coe',workspace:'workspace',partners:'workspace',resources:'frameworks',frameworks:'frameworks',methodology:'readiness',roadmap:'plan','transformation-roadmap':'plan'};
for(const [r,id] of Object.entries(TUTORIAL_CONTEXT)){const original=routes[r];if(!original)continue;routes[r]=()=>{const t=TUTORIALS.find(t=>t[0]===id);const card=`<aside class="contextual-tutorial"><span aria-hidden="true">▤</span><div><small>LEARN THIS STEP · PRACTICAL TUTORIAL</small><strong>${t[2]}</strong><p>Follow the walkthrough, try the tool and check your work.</p></div>${link('tutorial-'+id+'?from='+encodeURIComponent(r),'Start tutorial','button small secondary')}</aside>`;return original().replace('</section>', '</section>'+card);};}
const tutorialsHome=routes.home;
routes.home=()=>tutorialsHome().replace('<div class="guide-sidepaths">','<div class="tutorial-home-link"><span><b>Learn as you explore.</b> Practical walkthroughs for every stage.</span>'+link('tutorials','Explore tutorials','button small secondary')+'</div><div class="guide-sidepaths">');
const processBeforeLessonReturn=routes.process;
routes.process=()=>{const h=processBeforeLessonReturn();return tutorialQuery().get('lesson')==='goal'?h.replace('</section>','</section><aside class="contextual-tutorial"><div><strong>Continue your problem-definition lesson</strong><p>Your starter plan is saved. Return to review it whenever you need.</p></div>'+link('tutorial-goal','Return to problem lesson','button secondary')+'</aside>'):h;};
render(false);
